package in.tucor.api.buyer; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/buyer/pickups") public class BuyerPickupController {private final BuyerPickupRepository pickups;private final BuyerOrderRepository orders;private final MarketListingRepository listings;public BuyerPickupController(BuyerPickupRepository p,BuyerOrderRepository o,MarketListingRepository l){pickups=p;orders=o;listings=l;} public record PickupDto(String id,String orderId,String oilType,int volumeLiters,LocalDate scheduledDate,String status,String agentName,String vehicleNumber,String sellerCity,String notes){}
@GetMapping public List<PickupDto> list(Authentication a){UUID uid=UUID.fromString(a.getName());return pickups.findByBuyerIdOrderByCreatedAtDesc(uid).stream().map(this::dto).toList();}
private PickupDto dto(BuyerPickup p){BuyerOrder o=orders.findById(p.orderId).orElseThrow();MarketListing l=listings.findById(o.listingId).orElseThrow();return new PickupDto(p.publicId,o.publicId,l.oilType,o.volumeLiters,p.scheduledDate,p.status,p.agentName==null?"Unassigned":p.agentName,p.vehicleNumber==null?"—":p.vehicleNumber,l.city,p.notes);}}